import json, pathlib, re
root=pathlib.Path('/app/output')
obj=json.load(open('/app/benchmark/task_input.json'))
checks=obj['data_display']

html_files={p.name: p.read_text(encoding='utf-8') for p in root.glob('*.html')}

missing=[]
for c in checks:
  file = next((p for p in obj['pages'] if p['page_id']==c['page']), None)
  fname = file['file'] if file else None
  if not fname or fname not in html_files:
    missing.append((c['id'], 'file', fname))
    continue
  text=html_files[fname]
  # id presence
  if f'id="{c["id"]}"' not in text:
    missing.append((c['id'], 'id not found', fname))
  # expected content presence (all)
  for token in c.get('expected_content', []):
    if token not in text:
      missing.append((c['id'], f'missing token: {token}', fname))

print('missing count', len(missing))
for m in missing[:40]:
  print(m)
